1	/**
2	 * Scorer: browser-side scoring and comparison system.
3	 * Captures metrics, renders score cards, and manages a comparison drawer.
4	 * Uses localStorage for persistence across page loads.
5	 */
6	var Scorer = (function() {
7	    var STORAGE_KEY = 'pf_runs';
8	    var _idCounter  = 0;
9	
10	    // --- Storage helpers ---
11	
12	    function _loadFromStorage() {
13	        try {
14	            var raw = localStorage.getItem(STORAGE_KEY);
15	            return raw ? JSON.parse(raw) : [];
16	        } catch (e) {
17	            return [];
18	        }
19	    }
20	
21	    function _saveToStorage(runs) {
22	        try {
23	            localStorage.setItem(STORAGE_KEY, JSON.stringify(runs));
24	        } catch (e) {}
25	    }
26	
27	    // --- Core API ---
28	
29	    /**
30	     * Capture a run record from Controller state.
31	     * @param {string} algorithm     - finder name
32	     * @param {Object} grid          - PF.Grid instance (to extract walls)
33	     * @param {Array}  path          - [[x,y],...] result from finder
34	     * @param {number} timeMs        - elapsed time string or number
35	     * @param {number} nodesExplored - Controller.operationCount
36	     * @returns {Object} run record
37	     */
38	    function capture(algorithm, grid, path, timeMs, nodesExplored) {
39	        _idCounter += 1;
40	        var walls = [];
41	        if (grid && grid.nodes) {
42	            for (var y = 0; y < grid.height; y++) {
43	                for (var x = 0; x < grid.width; x++) {
44	                    if (!grid.nodes[y][x].walkable) {
45	                        walls.push([x, y]);
46	                    }
47	                }
48	            }
49	        }
50	        return {
51	            id:        Date.now() + '_' + _idCounter,
52	            algorithm: algorithm,
53	            timestamp: Date.now(),
54	            map: {
55	                width:  grid ? grid.width  : 0,
56	                height: grid ? grid.height : 0,
57	                walls:  walls
58	            },
59	            metrics: {
60	                nodesExplored: nodesExplored,
61	                pathLength:    path.length > 1 ? path.length - 1 : 0,
62	                timeMs:        parseFloat(timeMs)
63	            }
64	        };
65	    }
66	
67	    function save(run) {
68	        var runs = _loadFromStorage();
69	        runs.push(run);
70	        _saveToStorage(runs);
71	    }
72	
73	    function load() {
74	        return _loadFromStorage();
75	    }
76	
77	    function clear() {
78	        _saveToStorage([]);
79	    }
80	
81	    function compare() {
82	        return _loadFromStorage().map(function(run) {
83	            return {
84	                algorithm: run.algorithm,
85	                timestamp: run.timestamp,
86	                metrics:   run.metrics
87	            };
88	        });
89	    }
90	
91	    function scoreCard(run) {
92	        return {
93	            algorithm:     run.algorithm,
94	            timestamp:     run.timestamp,
95	            metrics:       run.metrics,
96	            formattedTime: parseFloat(run.metrics.timeMs).toFixed(4) + ' ms'
97	        };
98	    }
99	
100	    // --- UI rendering ---
101	
102	    function _formatDate(ts) {
103	        var d = new Date(ts);
104	        return d.toLocaleTimeString();
105	    }
106	
107	    function _renderCard(run) {
108	        var card = scoreCard(run);
109	        var $el = $('<div class="score-card">');
110	        $el.append(
111	            '<div class="score-card-header">' + card.algorithm + '</div>' +
112	            '<table class="score-card-table">' +
113	              '<tr><td>Nodes explored</td><td class="score-val">' + card.metrics.nodesExplored + '</td></tr>' +
114	              '<tr><td>Path length</td><td class="score-val">' + card.metrics.pathLength + '</td></tr>' +
115	              '<tr><td>Time</td><td class="score-val">' + card.formattedTime + '</td></tr>' +
116	              '<tr><td>Saved at</td><td class="score-val">' + _formatDate(card.timestamp) + '</td></tr>' +
117	            '</table>'
118	        );
119	        return $el;
120	    }
121	
122	    /** Show the score card panel after a run completes. */
123	    function showScoreCard(run) {
124	        var $panel = $('#score_panel');
125	        // Remove only previous card content, keep header with buttons intact
126	        $panel.find('.score-card').remove();
127	        // If header got destroyed (first render), rebuild it
128	        if ($panel.find('.score-panel-header').length === 0) {
129	            $panel.prepend(
130	                '<div class="score-panel-header">' +
131	                    '<span class="header_title">Run Results</span>' +
132	                    '<button id="save_run" class="score-action-btn">Save Run</button>' +
133	                    '<button id="compare_runs" class="score-action-btn">Compare</button>' +
134	                '</div>'
135	            );
136	        }
137	        $panel.append(_renderCard(run)).show();
138	    }
139	
140	    /** Open the comparison drawer with all saved runs. */
141	    function showComparisonDrawer() {
142	        var runs   = load();
143	        var $drawer = $('#comparison_drawer');
144	        $drawer.empty();
145	
146	        var $header = $('<div class="drawer-header">' +
147	            '<span>Saved Runs (' + runs.length + ')</span>' +
148	            '<button id="close_comparison">&#x2715;</button>' +
149	            '<button id="clear_runs">Clear All</button>' +
150	        '</div>');
151	        $drawer.append($header);
152	
153	        if (runs.length === 0) {
154	            $drawer.append('<p class="drawer-empty">No saved runs yet.</p>');
155	        } else {
156	            var $cards = $('<div class="drawer-cards">');
157	            runs.forEach(function(run) {
158	                $cards.append(_renderCard(run));
159	            });
160	            $drawer.append($cards);
161	        }
162	
163	        $drawer.show();
164	
165	        $('#close_comparison').off('click').on('click', hideComparisonDrawer);
166	        $('#clear_runs').off('click').on('click', function() {
167	            clear();
168	            showComparisonDrawer();
169	        });
170	    }
171	
172	    /** Close the comparison drawer. */
173	    function hideComparisonDrawer() {
174	        $('#comparison_drawer').hide();
175	    }
176	
177	    return {
178	        capture:              capture,
179	        save:                 save,
180	        load:                 load,
181	        clear:                clear,
182	        compare:              compare,
183	        scoreCard:            scoreCard,
184	        showScoreCard:        showScoreCard,
185	        showComparisonDrawer: showComparisonDrawer,
186	        hideComparisonDrawer: hideComparisonDrawer
187	    };
188	})();
189

