236	            enabled: true,
237	            callback: $.proxy(this.reset, this),
238	        });
239	        // => [starting, draggingStart, draggingEnd, drawingStart, drawingEnd]
240	    },
241	    onstarting: function(event, from, to) {
242	        console.log('=> starting');
243	        // Clears any existing search progress
244	        this.clearFootprints();
245	        this.setButtonStates({
246	            id: 2,
247	            enabled: true,
248	        });
