251	        $('#score_panel').hide();
252	        this.search();
253	        // => searching
254	    },
255	    onsearching: function() {
256	        console.log('=> searching');
257	        this.setButtonStates({
258	            id: 1,
259	            text: 'Restart Search',
260	            enabled: true,
261	            callback: $.proxy(this.restart, this),
262	        }, {
263	            id: 2,
264	            text: 'Pause Search',
265	            enabled: true,
266	            callback: $.proxy(this.pause, this),
267	        });
268	        // => [paused, finished]
269	    },
270	    onpaused: function() {
271	        console.log('=> paused');
272	        this.setButtonStates({
273	            id: 1,
274	            text: 'Resume Search',
275	            enabled: true,
276	            callback: $.proxy(this.resume, this),
277	        }, {
278	            id: 2,
279	            text: 'Cancel Search',
280	            enabled: true,
281	            callback: $.proxy(this.cancel, this),
282	        });
283	        // => [searching, ready]
284	    },
285	    onfinished: function() {
286	        console.log('=> finished');
287	        this.setButtonStates({
288	            id: 1,
289	            text: 'Restart Search',
290	            enabled: true,
291	            callback: $.proxy(this.restart, this),
292	        }, {
293	            id: 2,
294	            text: 'Clear Path',
295	            enabled: true,
296	            callback: $.proxy(this.clear, this),
297	        });
298	    },
299	    onmodified: function() {
300	        console.log('=> modified');
