306	        }, {
307	            id: 2,
308	            text: 'Clear Path',
309	            enabled: true,
310	            callback: $.proxy(this.clear, this),
311	        });
312	    },
313	
314	    /**
315	     * Define setters and getters of PF.Node, then we can get the operations
316	     * of the pathfinding.
317	     */
318	    hookPathFinding: function() {
319	
320	        PF.Node.prototype = {
321	            get opened() {
322	                return this._opened;
323	            },
324	            set opened(v) {
325	                this._opened = v;
326	                Controller.operations.push({
327	                    x: this.x,
328	                    y: this.y,
329	                    attr: 'opened',
330	                    value: v
331	                });
332	            },
333	            get closed() {
334	                return this._closed;
335	            },
336	            set closed(v) {
337	                this._closed = v;
338	                Controller.operations.push({
339	                    x: this.x,
340	                    y: this.y,
341	                    attr: 'closed',
342	                    value: v
343	                });
344	            },
345	            get tested() {
346	                return this._tested;
347	            },
348	            set tested(v) {
349	                this._tested = v;
350	                Controller.operations.push({
351	                    x: this.x,
352	                    y: this.y,
353	                    attr: 'tested',
354	                    value: v
355	                });
356	            },
357	        };
358	
359	        this.operations = [];
360	    },
361	    bindEvents: function() {
362	        $('#draw_area').mousedown($.proxy(this.mousedown, this));
363	        $(window)
364	            .mousemove($.proxy(this.mousemove, this))
365	            .mouseup($.proxy(this.mouseup, this));
366	    },
367	    loop: function() {
368	        var interval = 1000 / this.operationsPerSecond;
369	        (function loop() {
370	            if (!Controller.is('searching')) {
371	                return;
372	            }
373	            Controller.step();
374	            setTimeout(loop, interval);
375	        })();
376	    },
377	    step: function() {
378	        var operations = this.operations,
379	            op, isSupported;
380	
381	        do {
382	            if (!operations.length) {
383	                this.finish(); // transit to `finished` state
384	                return;
385	            }
386	            op = operations.shift();
387	            isSupported = View.supportedOperations.indexOf(op.attr) !== -1;
388	        } while (!isSupported);
389	
390	        View.setAttributeAt(op.x, op.y, op.attr, op.value);
391	    },
392	    clearOperations: function() {
393	        this.operations = [];
394	    },
395	    clearFootprints: function() {
396	        View.clearFootprints();
397	        View.clearPath();
398	    },
399	    clearAll: function() {
400	        this.clearFootprints();
401	        View.clearBlockedNodes();
402	    },
403	    buildNewGrid: function() {
404	        this.grid = new PF.Grid(this.gridSize[0], this.gridSize[1]);
405	    },
406	    mousedown: function (event) {
407	        var coord = View.toGridCoordinate(event.pageX, event.pageY),
408	            gridX = coord[0],
409	            gridY = coord[1],
410	            grid  = this.grid;
411	
412	        if (this.can('dragStart') && this.isStartPos(gridX, gridY)) {
413	            this.dragStart();
414	            return;
415	        }
416	        if (this.can('dragEnd') && this.isEndPos(gridX, gridY)) {
417	            this.dragEnd();
418	            return;
419	        }
420	        if (this.can('drawWall') && grid.isWalkableAt(gridX, gridY)) {
421	            this.drawWall(gridX, gridY);
422	            return;
423	        }
424	        if (this.can('eraseWall') && !grid.isWalkableAt(gridX, gridY)) {
425	            this.eraseWall(gridX, gridY);
426	        }
427	    },
428	    mousemove: function(event) {
429	        var coord = View.toGridCoordinate(event.pageX, event.pageY),
430	            grid = this.grid,
431	            gridX = coord[0],
432	            gridY = coord[1];
433	
434	        if (this.isStartOrEndPos(gridX, gridY)) {
435	            return;
436	        }
437	
438	        switch (this.current) {
439	        case 'draggingStart':
440	            if (grid.isWalkableAt(gridX, gridY)) {
441	                this.setStartPos(gridX, gridY);
442	            }
443	            break;
444	        case 'draggingEnd':
445	            if (grid.isWalkableAt(gridX, gridY)) {
446	                this.setEndPos(gridX, gridY);
447	            }
448	            break;
449	        case 'drawingWall':
450	            this.setWalkableAt(gridX, gridY, false);
451	            break;
452	        case 'erasingWall':
453	            this.setWalkableAt(gridX, gridY, true);
454	            break;
455	        }
456	    },
457	    mouseup: function(event) {
458	        if (Controller.can('rest')) {
459	            Controller.rest();
460	        }
461	    },
462	    setButtonStates: function() {
463	        $.each(arguments, function(i, opt) {
464	            var $button = Controller.$buttons.eq(opt.id - 1);
465	            if (opt.text) {
466	                $button.text(opt.text);
467	            }
468	            if (opt.callback) {
469	                $button
470	                    .unbind('click')
471	                    .click(opt.callback);
472	            }
473	            if (opt.enabled === undefined) {
474	                return;
475	            } else if (opt.enabled) {
476	                $button.removeAttr('disabled');
477	            } else {
478	                $button.attr({ disabled: 'disabled' });
479	            }
480	        });
481	    },
482	    /**
483	     * When initializing, this method will be called to set the positions
484	     * of start node and end node.
485	     * It will detect user's display size, and compute the best positions.
486	     */
487	    setDefaultStartEndPos: function() {
488	        var width, height,
489	            marginRight, availWidth,
490	            centerX, centerY,
491	            endX, endY,
492	            nodeSize = View.nodeSize;
493	
494	        width  = $(window).width();
495	        height = $(window).height();
496	
497	        marginRight = $('#algorithm_panel').width();
498	        availWidth = width - marginRight;
499	
500	        centerX = Math.ceil(availWidth / 2 / nodeSize);
501	        centerY = Math.floor(height / 2 / nodeSize);
502	
503	        this.setStartPos(centerX - 5, centerY);
504	        this.setEndPos(centerX + 5, centerY);
505	    },
506	    setStartPos: function(gridX, gridY) {
507	        this.startX = gridX;
508	        this.startY = gridY;
509	        View.setStartPos(gridX, gridY);
510	    },
511	    setEndPos: function(gridX, gridY) {
512	        this.endX = gridX;
513	        this.endY = gridY;
514	        View.setEndPos(gridX, gridY);
515	    },
516	    setWalkableAt: function(gridX, gridY, walkable) {
517	        this.grid.setWalkableAt(gridX, gridY, walkable);
518	        View.setAttributeAt(gridX, gridY, 'walkable', walkable);
519	    },
520	    isStartPos: function(gridX, gridY) {
521	        return gridX === this.startX && gridY === this.startY;
522	    },
523	    isEndPos: function(gridX, gridY) {
524	        return gridX === this.endX && gridY === this.endY;
525	    },
526	    isStartOrEndPos: function(gridX, gridY) {
527	        return this.isStartPos(gridX, gridY) || this.isEndPos(gridX, gridY);
528	    },
529	});
530

